/// Deep-merge `over` INTO `base`: for objects, recurse key-by-key; a NULL in `over` means "leave the
/// base default" (never overwrite a real default with null); any non-object leaf in `over` replaces base.
fn merge_json(base: &mut serde_json::Value, over: serde_json::Value) {
    match (base, over) {
        (serde_json::Value::Object(b), serde_json::Value::Object(o)) => {
            for (k, v) in o {
                if v.is_null() {
                    continue;
                }
                merge_json(b.entry(k).or_insert(serde_json::Value::Null), v);
            }
        }
        (b, o) => *b = o,
    }
}

/// Load the swarm config with the STRUCT DEFAULT as the base, so a key OMITTED from config.yaml keeps the
/// intended default rather than serde's TYPE default (None/false).
///
/// `get_param::<SwarmConfig>()` deserializes the `swarm:` block directly, and serde fills a missing key with
/// the FIELD TYPE's default (None/false), NOT the `Default for SwarmConfig` value — so every non-type
/// default (e.g. `sink_max_turns: Some(120)`, the whole baked golden formula) was silently reverted whenever
/// a swarm block existed, which is always. Merging the raw config OVER `SwarmConfig::default()` fixes the
/// entire class at once, and makes the resolvers correct too (a `cfg.unwrap_or(false)` now sees the merged
/// `Some(golden)`). Falls back to the old typed read on any serialization hiccup, so it can only be safer.
fn load_config() -> SwarmConfig {
    let cfg = Config::global();
    let Ok(mut base) = serde_json::to_value(SwarmConfig::default()) else {
        return cfg
            .get_param::<SwarmConfig>(SWARM_CONFIG_KEY)
            .unwrap_or_default();
    };
    if let Ok(raw) = cfg.get(SWARM_CONFIG_KEY, false) {
        merge_json(&mut base, raw);
    }
    serde_json::from_value(base).unwrap_or_else(|_| {
        cfg.get_param::<SwarmConfig>(SWARM_CONFIG_KEY)
            .unwrap_or_default()
    })
}

fn save_config(cfg: &SwarmConfig) -> Result<()> {
    Config::global()
        .set_param(SWARM_CONFIG_KEY, cfg)
        .map_err(|e| anyhow!("failed to save swarm config: {e}"))
}

// ---------------------------------------------------------------------------------------------
// CLI surface
// ---------------------------------------------------------------------------------------------

#[derive(clap::Subcommand, Debug)]
pub enum SwarmCommand {
    /// Plan a task and run it across the swarm device pool.
    Run {
        /// The task to plan and run.
        prompt: String,
        /// Final report format: `text` (default) or `json` (the enriched RunReport to stdout).
        #[arg(long = "output-format", default_value = "text")]
        output_format: String,
        /// Path for the structured JSONL event log (default: <cwd>/.swarm/run-<id>.jsonl).
        #[arg(long = "log-file")]
        log_file: Option<PathBuf>,
        /// Disable the JSONL event log.
        #[arg(long = "no-log")]
        no_log: bool,
        /// Override per-worker max turns (default: the pool's worker_max_turns).
        #[arg(long = "max-turns")]
        max_turns: Option<u32>,
        /// Enable an MCP worker extension for this run (repeatable): context7 | web-search | doc-processor.
        #[arg(long = "mcp")]
        mcp: Vec<String>,
        /// Force the research-planning phase on/off for this run (overrides the configured mode).
        #[arg(long = "research")]
        research: Option<bool>,
        /// Force dynamic replanning on/off for this run (overrides the configured setting).
        #[arg(long = "dynamic-replan")]
        dynamic_replan: Option<bool>,
        /// Draft N plan skeletons in parallel and pick the best (overrides config; 1 = off).
        #[arg(long = "best-of-n")]
        best_of_n: Option<usize>,
    },
    /// View and manage the swarm device pool (interactive menu when no subcommand is given).
    Pool {
        #[command(subcommand)]
        command: Option<PoolCommand>,
    },
    /// Serve the swarm as an MCP extension over stdio, so an interactive `goose session` can offload work
    /// to the local worker fleet. Scaffold: a read-only `swarm_status` tool (async dispatch/collect later).
    #[command(
        about = "Serve the swarm as an MCP extension over stdio (goose session --with-extension)"
    )]
    Serve,
}

/// Options for a `goose swarm run`.
pub struct RunOpts {
    pub prompt: String,
    pub output_format: String,
    pub log_file: Option<PathBuf>,
    pub no_log: bool,
    pub max_turns: Option<u32>,
    pub mcp: Vec<String>,
    pub research: Option<bool>,
    pub dynamic_replan: Option<bool>,
    pub best_of_n: Option<usize>,
}

#[derive(clap::Subcommand, Debug)]
pub enum PoolCommand {
    /// Print the current pool.
    Show,
    /// Add a device.
    Add {
        id: String,
        model_id: String,
        #[arg(default_value_t = 1)]
        weight: u32,
        #[arg(default_value_t = 1)]
        instances: u32,
    },
    /// Remove a device by id.
    Rm { id: String },
    /// Set a device's weight.
    Weight { id: String, weight: u32 },
    /// Enable a device.
    Enable { id: String },
    /// Disable a device.
    Disable { id: String },
    /// Probe the live fleet (lms ps + the endpoint's model ids).
    Probe,
    /// Import every model loaded across the fleet (parses `lms ps`) as pool entries.
    Import {
        #[arg(long, default_value_t = 1)]
        weight: u32,
        #[arg(long)]
        disabled: bool,
    },
}

pub async fn handle_swarm(cmd: SwarmCommand) -> Result<()> {
    match cmd {
        SwarmCommand::Run {
            prompt,
            output_format,
            log_file,
            no_log,
            max_turns,
            mcp,
            research,
            dynamic_replan,
            best_of_n,
        } => {
            run_swarm(RunOpts {
                prompt,
                output_format,
                log_file,
                no_log,
                max_turns,
                mcp,
                research,
                dynamic_replan,
                best_of_n,
            })
            .await
        }
        SwarmCommand::Pool { command } => match command {
            None => pool_menu(),
            Some(pc) => pool_op(pc),
        },
        SwarmCommand::Serve => crate::commands::swarm_serve::run().await,
    }
}

// ---------------------------------------------------------------------------------------------
// Pool management
// ---------------------------------------------------------------------------------------------

fn show_pool(cfg: &SwarmConfig) {
    println!("\n{}", style(" swarm pool ").on_cyan().black().bold());
    println!("  endpoint   {}", style(&cfg.endpoint).cyan());
    println!(
        "  planner    {}   also-works {} (w{})",
        style(&cfg.planner_model).green(),
        if cfg.planner_also_works {
            style("on").green().bold()
        } else {
            style("off").red().bold()
        },
        cfg.planner_weight
    );
    println!(
        "  limits     worker-max-turns {}   max-attempts {}   context-cap {}",
        style(cfg.worker_max_turns).cyan(),
        style(cfg.max_attempts).cyan(),
        match cfg.context_cap {
            Some(c) => style(c.to_string()).cyan(),
            None => style("off".to_string()).dim(),
        }
    );
    println!(
        "  research   {:?}   max-questions {}   mode {}",
        cfg.research_planning,
        style(cfg.max_research_questions).cyan(),
        if cfg.research_scouts {
            style("scouts(parallel)").green().bold()
        } else {
            style("questions").cyan()
        }
    );
    println!(
        "  planning   {}",
        if cfg.parallel_planning {
            style("parallel (skeleton + fleet detailing)")
                .green()
                .bold()
        } else {
            style("solo 27B").cyan()
        }
    );
    println!(
        "  identical  {}",
        if cfg.homogeneous_models {
            style("yes — split aggressively (same tokenizer)")
                .green()
                .bold()
        } else {
            style("no").dim()
        }
    );
    if !cfg.speed_weights.is_empty() {
        let mut sw: Vec<String> = cfg
            .speed_weights
            .iter()
            .map(|(k, v)| format!("{k}={v}"))
            .collect();
        sw.sort();
        println!(
            "  speed-wt   {}",
            style(format!("{} (faster host → more tasks)", sw.join(" "))).green()
        );
    }
    println!(
        "  skeletons  {}",
        if cfg.best_of_n_skeletons > 1 {
            style(format!(
                "best-of-{} (parallel draft + structural score)",
                cfg.best_of_n_skeletons
            ))
            .green()
            .bold()
        } else {
            style("single".to_string()).dim()
        }
    );
    println!(
        "  idle-cap   worker {}s · planner {}s (NO-PROGRESS window, not wall-clock; a stalled stream re-routes / falls back)",
        style(cfg.worker_timeout_secs).cyan(),
        style(cfg.planner_timeout_secs).cyan()
    );
    println!(
        "  models     load {}",
        if cfg.allow_model_load {
            style("ON (swarm may lms-load / pre-warm)").green().bold()
        } else {
            style("OFF (resident models only — no auto spin-up)")
                .yellow()
                .bold()
        }
    );
    {
        let mut parts: Vec<String> = Vec::new();
        if let Some(v) = cfg.temperature {
            parts.push(format!("temp={v}"));
        }
        if let Some(v) = cfg.top_p {
            parts.push(format!("top_p={v}"));
        }
        if let Some(v) = cfg.top_k {
            parts.push(format!("top_k={v}"));
        }
        if let Some(v) = cfg.min_p {
            parts.push(format!("min_p={v}"));
        }
        if let Some(v) = cfg.repeat_penalty {
            parts.push(format!("rep={v}"));
        }
        let s = if parts.is_empty() {
            style("model defaults".to_string()).dim()
        } else {
            style(parts.join(" ")).cyan().bold()
        };
        println!("  sampling   {s}");
    }
    println!(
        "  replan     {}   max-rounds {}",
        if cfg.dynamic_replan {
            style("on").green().bold()
        } else {
            style("off").red().bold()
        },
        style(cfg.max_replans).cyan()
    );
    println!(
        "  mcp        {}",
        if cfg.worker_extensions.is_empty() {
            style("none".to_string()).dim()
        } else {
            style(cfg.worker_extensions.join(", ")).cyan()
        }
    );
    if cfg.devices.is_empty() {
        println!("  {}", style("(no devices — add one)").yellow());
        return;
    }
    for d in &cfg.devices {
        let state = if d.enabled {
            style("enabled ").green().bold()
        } else {
            style("disabled").red().bold()
        };
        println!(
            "  {state}  {:<10} weight {}  ×{} inst  {}{}",
            style(&d.id).bold(),
            style(d.weight).cyan().bold(),
            style(d.instances).cyan(),
            style(&d.model_id).dim(),
            style(
                d.host
                    .as_deref()
                    .map(|h| format!("  @{h}"))
                    .unwrap_or_default()
            )
            .dim()
        );
    }
}

fn pool_menu() -> Result<()> {
    let mut cfg = load_config();
    cliclack::intro(style(" goose swarm pool ").on_cyan().black())?;
    loop {
        show_pool(&cfg);
        let action: &str = cliclack::select("Manage the device pool")
            .item("add", "Add a device", "")
            .item("weight", "Set a device weight", "")
            .item("instances", "Set device instance count", "copies to load")
            .item("toggle", "Enable / disable a device", "")
            .item("remove", "Remove a device", "")
            .item("planner", "Set the planner model", "")
            .item("planner-worker", "Planner-also-works on/off + weight", "")
            .item("endpoint", "Set the LM Link endpoint", "")
            .item("max-turns", "Set worker max-turns", "")
            .item("max-attempts", "Set max dispatch attempts", "")
            .item(
                "context-cap",
                "Set context-window cap",
                "GOOSE_LOCAL_CONTEXT_CAP",
            )
            .item("research", "Research-planning mode", "off / on / auto")
            .item(
                "scouts",
                "Research method",
                "parallel scouts vs serial scoping",
            )
            .item(
                "planning",
                "Planning method",
                "parallel fleet detailing vs solo 27B",
            )
            .item(
                "homogeneous",
                "Identical models",
                "same tokenizer -> split aggressively",
            )
            .item(
                "best-of-n",
                "Best-of-N skeletons",
                "draft N plans in parallel, pick the best (1 = off)",
            )
            .item(
                "model-load",
                "Allow model loading",
                "let the swarm lms-load / pre-warm (off = resident only)",
            )
            .item("max-research", "Max research questions / lenses", "")
            .item(
                "replan",
                "Dynamic replan on/off",
                "fill idle workers mid-run",
            )
            .item("max-replans", "Max replan rounds", "")
            .item(
                "mcp",
                "Toggle worker MCP extensions",
                "context7 / web-search / doc-processor",
            )
            .item("probe", "Probe the live fleet", "lms ps + endpoint models")
            .item(
                "import",
                "Import loaded models from fleet",
                "lms ps -> pool entries",
            )
            .item("save", "Save & exit", "")
            .item("quit", "Quit without saving", "")
            .interact()?;
        match action {
            "add" => {
                let id: String = cliclack::input("Device id (e.g. workhorse)").interact()?;
                let model_id: String =
                    cliclack::input("LM Link model id (must be unique)").interact()?;
                let weight: String = cliclack::input("Weight (max concurrent tasks)")
                    .default_input("1")
                    .interact()?;
                let weight: u32 = weight.trim().parse().unwrap_or(1).max(1);
                let instances: String = cliclack::input("Instances to load on this device")
                    .default_input("1")
                    .interact()?;
                let instances: u32 = instances.trim().parse().unwrap_or(1).max(1);
                cfg.devices.retain(|d| d.id != id);
                cfg.devices.push(SwarmDevice {
                    id,
                    model_id,
                    weight,
                    enabled: true,
                    instances,
                    host: None,
                });
            }
            "weight" => {
                if let Some(id) = pick_device(&cfg, "Set weight for which device?")? {
                    let weight: String =
                        cliclack::input(format!("New weight for {id}")).interact()?;
                    let weight: u32 = weight.trim().parse().unwrap_or(1).max(1);
                    if let Some(d) = cfg.devices.iter_mut().find(|d| d.id == id) {
                        d.weight = weight;
                    }
                }
            }
            "instances" => {
                if let Some(id) = pick_device(&cfg, "Set instances for which device?")? {
                    let n: String = cliclack::input(format!("Instances for {id}")).interact()?;
                    let n: u32 = n.trim().parse().unwrap_or(1).max(1);
                    if let Some(d) = cfg.devices.iter_mut().find(|d| d.id == id) {
                        d.instances = n;
                    }
                }
            }
            "toggle" => {
                if let Some(id) = pick_device(&cfg, "Enable/disable which device?")? {
                    if let Some(d) = cfg.devices.iter_mut().find(|d| d.id == id) {
                        d.enabled = !d.enabled;
                    }
                }
            }
            "remove" => {
                if let Some(id) = pick_device(&cfg, "Remove which device?")? {
                    cfg.devices.retain(|d| d.id != id);
                }
            }
            "planner" => {
                let m: String = cliclack::input("Planner model id")
                    .default_input(&cfg.planner_model)
                    .interact()?;
                cfg.planner_model = m;
            }
            "planner-worker" => {
                cfg.planner_also_works = cliclack::confirm("Planner also works as a worker?")
                    .initial_value(cfg.planner_also_works)
                    .interact()?;
                if cfg.planner_also_works {
                    let w: String = cliclack::input("Planner worker weight")
                        .default_input(&cfg.planner_weight.to_string())
                        .interact()?;
                    cfg.planner_weight = w.trim().parse().unwrap_or(1).max(1);
                }
            }
            "endpoint" => {
                let e: String = cliclack::input("LM Link endpoint")
                    .default_input(&cfg.endpoint)
                    .interact()?;
                cfg.endpoint = e;
            }
            "max-turns" => {
                let v: String = cliclack::input("Worker max-turns")
                    .default_input(&cfg.worker_max_turns.to_string())
                    .interact()?;
                cfg.worker_max_turns = v.trim().parse().unwrap_or(40).max(1);
            }
            "max-attempts" => {
                let v: String = cliclack::input("Max dispatch attempts")
                    .default_input(&cfg.max_attempts.to_string())
                    .interact()?;
                cfg.max_attempts = v.trim().parse().unwrap_or(3).max(1);
            }
            "context-cap" => {
                let cur = cfg
                    .context_cap
                    .map(|c| c.to_string())
                    .unwrap_or_else(|| "0".to_string());
                let v: String = cliclack::input("Context cap tokens (0 = off)")
                    .default_input(&cur)
                    .interact()?;
                let parsed: u32 = v.trim().parse().unwrap_or(0);
                cfg.context_cap = if parsed == 0 { None } else { Some(parsed) };
            }
            "research" => {
                let m: &str = cliclack::select("Research-planning mode")
                    .item("off", "off", "")
                    .item("on", "on", "")
                    .item("auto", "auto", "on for amendments only")
                    .interact()?;
                cfg.research_planning = match m {
                    "off" => ResearchPlanningMode::Off,
                    "on" => ResearchPlanningMode::On,
                    _ => ResearchPlanningMode::Auto,
                };
            }
            "scouts" => {
                cfg.research_scouts =
                    cliclack::confirm("Use parallel fixed-lens scouts (no serial scoping call)?")
                        .initial_value(cfg.research_scouts)
                        .interact()?;
            }
            "planning" => {
                cfg.parallel_planning =
                    cliclack::confirm("Parallel planning (27B skeleton + fleet detailing)?")
                        .initial_value(cfg.parallel_planning)
                        .interact()?;
            }
            "homogeneous" => {
                cfg.homogeneous_models = cliclack::confirm(
                    "All worker models identical (same tokenizer)? Enables aggressive splitting",
                )
                .initial_value(cfg.homogeneous_models)
                .interact()?;
            }
            "best-of-n" => {
                let v: String =
                    cliclack::input("How many skeleton candidates to draft in parallel (1 = off)")
                        .default_input(&cfg.best_of_n_skeletons.to_string())
                        .interact()?;
                cfg.best_of_n_skeletons = v.trim().parse().unwrap_or(1).clamp(1, 5);
            }
            "model-load" => {
                cfg.allow_model_load = cliclack::confirm(
                    "Allow the swarm to load models (lms load / pre-warm)? Off = use only resident models",
                )
                .initial_value(cfg.allow_model_load)
                .interact()?;
            }
            "max-research" => {
                let v: String = cliclack::input("Max research questions / scout lenses")
                    .default_input(&cfg.max_research_questions.to_string())
                    .interact()?;
                cfg.max_research_questions = v.trim().parse().unwrap_or(4).clamp(1, 8);
            }
            "replan" => {
                cfg.dynamic_replan =
                    cliclack::confirm("Dynamic replanning (fill idle workers mid-run)?")
                        .initial_value(cfg.dynamic_replan)
                        .interact()?;
            }
            "max-replans" => {
                let v: String = cliclack::input("Max replan rounds")
                    .default_input(&cfg.max_replans.to_string())
                    .interact()?;
                cfg.max_replans = v.trim().parse().unwrap_or(2).clamp(0, 6);
            }
            "mcp" => {
                let choice: &str = cliclack::select("Toggle which worker MCP extension?")
                    .item("context7", "context7", "")
                    .item("web-search", "web-search", "")
                    .item("doc-processor", "doc-processor", "")
                    .interact()?;
                if let Some(pos) = cfg.worker_extensions.iter().position(|x| x == choice) {
                    cfg.worker_extensions.remove(pos);
                } else {
                    cfg.worker_extensions.push(choice.to_string());
                }
            }
            "probe" => probe_fleet(),
            "import" => match probe_lms_processes() {
                Ok(procs) if !procs.is_empty() => {
                    let summary = import_processes(&mut cfg, &procs, 1, true);
                    print_import_summary(&summary);
                }
                Ok(_) => println!("  {}", style("(no models loaded on the fleet)").yellow()),
                Err(e) => println!("  (lms ps failed: {e})"),
            },
            "save" => {
                save_config(&cfg)?;
                cliclack::outro(style("pool saved").green())?;
                break;
            }
            "quit" => {
                cliclack::outro(style("not saved").yellow())?;
                break;
            }
            _ => {}
        }
    }
    Ok(())
}

fn pick_device(cfg: &SwarmConfig, prompt: &str) -> Result<Option<String>> {
    if cfg.devices.is_empty() {
        println!("  {}", style("(no devices)").yellow());
        return Ok(None);
    }
    let mut sel = cliclack::select(prompt.to_string());
    for d in &cfg.devices {
        sel = sel.item(d.id.clone(), &d.id, &d.model_id);
    }
    Ok(Some(sel.interact()?))
}

fn pool_op(pc: PoolCommand) -> Result<()> {
    let mut cfg = load_config();
    match pc {
        PoolCommand::Show => {
            show_pool(&cfg);
            return Ok(());
        }
        PoolCommand::Probe => {
            probe_fleet();
            return Ok(());
        }
        PoolCommand::Import { weight, disabled } => {
            let procs = probe_lms_processes()?;
            let summary = import_processes(&mut cfg, &procs, weight, !disabled);
            print_import_summary(&summary);
        }
        PoolCommand::Add {
            id,
            model_id,
            weight,
            instances,
        } => {
            cfg.devices.retain(|d| d.id != id);
            cfg.devices.push(SwarmDevice {
                id,
                model_id,
                weight: weight.max(1),
                enabled: true,
                instances: instances.max(1),
                host: None,
            });
        }
        PoolCommand::Rm { id } => cfg.devices.retain(|d| d.id != id),
        PoolCommand::Weight { id, weight } => {
            if let Some(d) = cfg.devices.iter_mut().find(|d| d.id == id) {
                d.weight = weight.max(1);
            }
        }
        PoolCommand::Enable { id } => {
            if let Some(d) = cfg.devices.iter_mut().find(|d| d.id == id) {
                d.enabled = true;
            }
        }
        PoolCommand::Disable { id } => {
            if let Some(d) = cfg.devices.iter_mut().find(|d| d.id == id) {
                d.enabled = false;
            }
        }
    }
    save_config(&cfg)?;
    show_pool(&cfg);
    Ok(())
}

/// Resolve the `lms` CLI binary. A Finder-launched desktop app does NOT inherit the shell PATH, so a bare
/// `lms` is not found — the GUI swarm bailed with "no models loaded" despite a loaded fleet. Check an
/// explicit override, then LM Studio's default install locations, else fall back to PATH.
fn resolve_lms() -> String {
    if let Ok(p) = std::env::var("SWARM_LMS_PATH") {
        if !p.trim().is_empty() {
            return p;
        }
    }
    if let Ok(home) = std::env::var("HOME") {
        for rel in [".lmstudio/bin/lms", ".cache/lm-studio/bin/lms"] {
            let cand = std::path::Path::new(&home).join(rel);
            if cand.is_file() {
                return cand.to_string_lossy().into_owned();
            }
        }
    }
    "lms".to_string()
}

/// The LM Studio HTTP host for the fallback probe (LMSTUDIO_HOST, else the default local server).
fn lms_http_host() -> String {
    std::env::var("LMSTUDIO_HOST")
        .ok()
        .filter(|s| !s.trim().is_empty())
        .unwrap_or_else(|| "http://localhost:1234".to_string())
}

/// Node/device name from an LM Link model id: the prefix before the first '-' (mihai-, workhorse-, gabee-).
fn device_from_lms_id(id: &str) -> Option<String> {
    let bare = id.rsplit('/').next().unwrap_or(id);
    bare.split_once('-').map(|(prefix, _)| prefix.to_string())
}

/// Discover loaded models straight from the LM Studio HTTP server (native /api/v0/models) — the fallback
/// for when the `lms` CLI is missing/unreachable (a Finder-launched desktop app has no lms on PATH). The
/// HTTP server MUST be up for the swarm to call the models at all, so it is the robust source. Uses `curl`
/// (a system binary present on the minimal GUI PATH) to avoid a blocking HTTP call inside the async
/// runtime. Returns loaded, non-embedding models as LmsProcess entries (device derived from the id prefix).
fn probe_lms_http() -> Vec<LmsProcess> {
    let url = format!("{}/api/v0/models", lms_http_host().trim_end_matches('/'));
    let Ok(out) = ProcCommand::new("curl")
        .args(["-s", "--max-time", "6", &url])
        .output()
    else {
        return Vec::new();
    };
    let Ok(json) = serde_json::from_slice::<serde_json::Value>(&out.stdout) else {
        return Vec::new();
    };
    let Some(arr) = json.get("data").and_then(|v| v.as_array()) else {
        return Vec::new();
    };
    arr.iter()
        .filter(|m| {
            m.get("state").and_then(|v| v.as_str()) == Some("loaded")
                && m.get("type").and_then(|v| v.as_str()) != Some("embeddings")
        })
        .filter_map(|m| {
            let id = m
                .get("id")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            if id.is_empty() {
                return None;
            }
            Some(LmsProcess {
                device: device_from_lms_id(&id),
                identifier: id,
                status: "loaded".to_string(),
                parallel: None,
            })
        })
        .collect()
}

/// The model ids the ENDPOINT will actually serve — i.e. the only ids a worker can dispatch to.
///
/// `None` means the probe itself failed (endpoint down, curl missing, unparseable body). That is NOT the
/// same as "no models", and the caller must never gate on it: an instrument reporting zero has been wrong
/// seven times in this project, and gating a whole run off a failed probe would be the eighth.
///
/// WHY THIS IS NOT `lms ps`: `lms ps` lists what is RESIDENT; `/v1/models` lists what is SERVABLE, and they
/// disagree in exactly the case that costs a run. MEASURED 2026-07-17: `lms ps` showed
/// `workhorse-qwopus3.6-27b-coder-mlx` IDLE and loaded, while POSTing to it returned
/// `400 Invalid model identifier` — the Mac Studio had dropped off the LAN and LM Link had withdrawn the
/// alias, but the resident list still carried it. The pool is built from `lms ps`, so the swarm cheerfully
/// dispatched a third of its tasks into an instant 400.
fn endpoint_model_ids() -> Option<std::collections::HashSet<String>> {
    let url = format!("{}/v1/models", lms_http_host().trim_end_matches('/'));
    let out = ProcCommand::new("curl")
        .args(["-s", "--max-time", "6", &url])
        .output()
        .ok()?;
    let json = serde_json::from_slice::<serde_json::Value>(&out.stdout).ok()?;
    let arr = json.get("data")?.as_array()?;
    let ids: std::collections::HashSet<String> = arr
        .iter()
        .filter_map(|m| m.get("id").and_then(|i| i.as_str()).map(str::to_string))
        .collect();
    if ids.is_empty() {
        return None;
    }
    Some(ids)
}

/// Drop devices the endpoint will not serve, so a dead node cannot silently eat a third of the run.
///
/// THE FAILURE THIS PREVENTS, measured end-to-end on a 71-minute run that produced nothing:
/// the `frontend` task was dispatched to a model the endpoint had withdrawn. Every attempt came back
/// `400 Invalid model identifier` in ~2s. But `run_agent_in` returns Ok for a provider error — the 400 lands
/// as the agent's *text* — so the dispatcher saw only "worker finished, owned files absent" and retried with
/// "You finished WITHOUT writing your owned file(s)". Three attempts, 6.8 seconds, zero tool calls, task
/// failed. `integrate-verify` depends on every task, so it never became ready, and the run ended with
/// passed=false having never built the app. The engine blamed the model for a network outage.
///
/// Returns the surviving devices and the dropped (id, model_id) pairs.
///
/// NEVER EMPTIES THE POOL. If every device would be dropped, the probe disagrees with `lms ps` about
/// literally everything, and the likeliest explanation is a broken probe — not a fleet that is 100% dead.
/// Keep the pool, report nothing dropped, and let the run proceed as it did before this function existed.
fn drop_unservable_devices(
    devices: Vec<SwarmDevice>,
    served: Option<&std::collections::HashSet<String>>,
) -> (Vec<SwarmDevice>, Vec<(String, String)>) {
    let Some(served) = served else {
        return (devices, Vec::new());
    };
    let (keep, drop): (Vec<SwarmDevice>, Vec<SwarmDevice>) = devices
        .into_iter()
        .partition(|d| served.contains(&d.model_id));
    if keep.is_empty() {
        return (drop, Vec::new());
    }
    let dropped = drop.into_iter().map(|d| (d.id, d.model_id)).collect();
    (keep, dropped)
}

/// The no-start guard (#128) is ON unless explicitly killed. It only ever ADDS a refusal on a PROVEN negative,
/// so the safe direction is on; the kill-switch exists so a misfiring probe can be worked around without a
/// rebuild. Env only (not a persisted config field) on purpose: a safety guard should not be silently disabled
/// by a stale serialized config, and a bare-bool `#[serde(default)]` would deserialize to false = off.
fn require_servable() -> bool {
    match std::env::var("GOOSE_SWARM_REQUIRE_SERVABLE") {
        Ok(v) => !matches!(v.trim(), "0" | "false" | "off" | "no"),
        Err(_) => true,
    }
}

/// PROVEN-zero-servable: refuse ONLY when the `/v1/models` catalog demonstrably WORKS (it returned a non-empty
/// list — a positive control on the SAME endpoint) yet lists NONE of the resident pool's models. That is a
/// negative PROVEN on the same object, not an observed-empty: `endpoint_model_ids` collapses an empty/unreachable
/// probe to `None`, and `served == None` never refuses. So this can only fire when every resident alias has been
/// withdrawn (the LM Link node dropped off the LAN) — the exact case where proceeding dispatches a third (or all)
/// of the run into instant 400s and a dead run. It can NEVER authorize a bad dispatch — only stop one — so it is
/// structurally incapable of the false-"there are models" mistake.
fn all_resident_unservable(
    pool: &[SwarmDevice],
    served: Option<&std::collections::HashSet<String>>,
) -> bool {
    match served {
        Some(s) if !s.is_empty() && !pool.is_empty() => {
            pool.iter().all(|d| !s.contains(&d.model_id))
        }
        _ => false,
    }
}

fn probe_fleet() {
    println!("\n{}", style("lms ps:").bold());
    match ProcCommand::new(resolve_lms()).arg("ps").output() {
        Ok(out) => print!("{}", String::from_utf8_lossy(&out.stdout)),
        Err(e) => println!("  (lms ps failed: {e})"),
    }
    println!("{}", style("endpoint model ids:").bold());
    let models_url = format!("{}/v1/models", lms_http_host().trim_end_matches('/'));
    match ProcCommand::new("curl")
        .args(["-s", "--max-time", "6", &models_url])
        .output()
    {
        Ok(out) => {
            let body = String::from_utf8_lossy(&out.stdout);
            if let Ok(v) = serde_json::from_str::<serde_json::Value>(&body) {
                if let Some(arr) = v.get("data").and_then(|d| d.as_array()) {
                    for m in arr {
                        if let Some(id) = m.get("id").and_then(|i| i.as_str()) {
                            println!("  {id}");
                        }
                    }
                }
            }
        }
        Err(e) => println!("  (curl failed: {e})"),
    }
}

/// Count currently-loaded instances of a model across the fleet (`lms ps`).
fn loaded_instance_count(model_id: &str) -> usize {
    match ProcCommand::new(resolve_lms()).arg("ps").output() {
        Ok(out) => String::from_utf8_lossy(&out.stdout)
            .lines()
            .filter(|l| l.contains(model_id))
            .count(),
        Err(_) => 0,
    }
}

/// Ensure up to `instances` copies of a model are loaded — and NEVER more than already present, so
/// repeated runs / pre-warms don't stack duplicate instances (the cause of "3 instances on one box").
/// Default `instances` is 1, so goose never spins up extras unless the user raises it.
fn ensure_loaded(model_id: &str, instances: u32) {
    let want = instances.max(1) as usize;
    let have = loaded_instance_count(model_id);
    for _ in have..want {
        let _ = ProcCommand::new(resolve_lms())
            .args(["load", model_id, "-y", "--ttl", "3600"])
            .output();
    }
}

// ---------------------------------------------------------------------------------------------
// Fleet import — parse `lms ps` and add every loaded model (one per machine, or several) to the pool
// ---------------------------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq)]
struct LmsProcess {
    identifier: String,
    status: String,
    device: Option<String>,
    /// LM Studio's PARALLEL column — how many requests this model instance serves at once. The swarm
    /// uses it as the device weight so dispatch concurrency tracks the user's LM Studio concurrency.
    parallel: Option<u32>,
}

/// Parse `lms ps` output (a plain whitespace-aligned table). Splits data rows on runs of >=2 spaces
/// (so "29.53 GB" stays one field) and reads DEVICE by its header column index. Errs if no header.
fn parse_lms_ps(raw: &str) -> Result<Vec<LmsProcess>> {
    let ansi = regex::Regex::new(r"\x1b\[[0-9;]*m").unwrap();
    let gap = regex::Regex::new(r"\s{2,}").unwrap();
    let clean = ansi.replace_all(raw, "");
    let lines: Vec<&str> = clean.lines().collect();
    let header = lines
        .iter()
        .position(|l| l.contains("IDENTIFIER") && l.contains("DEVICE"))
        .ok_or_else(|| anyhow!("lms ps: header (IDENTIFIER/DEVICE) not found"))?;
    let cols: Vec<&str> = lines[header].split_whitespace().collect();
    let device_idx = cols.iter().position(|c| *c == "DEVICE").unwrap_or(6);
    let status_idx = cols.iter().position(|c| *c == "STATUS").unwrap_or(2);
    let parallel_idx = cols.iter().position(|c| *c == "PARALLEL");
    let mut out = Vec::new();
    for line in &lines[header + 1..] {
        if line.trim().is_empty() {
            continue;
        }
        let f: Vec<String> = gap
            .split(line.trim())
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
        if f.is_empty() {
            continue;
        }
        out.push(LmsProcess {
            identifier: f[0].clone(),
            status: f.get(status_idx).cloned().unwrap_or_default(),
            device: f.get(device_idx).cloned().filter(|s| !s.is_empty()),
            parallel: parallel_idx
                .and_then(|i| f.get(i))
                .and_then(|s| s.parse::<u32>().ok()),
        });
    }
    Ok(out)
}

fn probe_lms_processes() -> Result<Vec<LmsProcess>> {
    // Primary: the `lms` CLI (richest — carries DEVICE + PARALLEL). Resolve its real path since a
    // Finder-launched app has no lms on PATH.
    if let Ok(out) = ProcCommand::new(resolve_lms()).arg("ps").output() {
        if out.status.success() {
            if let Ok(procs) = parse_lms_ps(&String::from_utf8_lossy(&out.stdout)) {
                if !procs.is_empty() {
                    return Ok(procs);
                }
            }
        }
    }
    // Fallback: the LM Studio HTTP server (no lms CLI needed). Empty if the server is unreachable too.
    Ok(probe_lms_http())
}

fn short_model(identifier: &str) -> String {
    identifier
        .rsplit('/')
        .next()
        .unwrap_or(identifier)
        .to_lowercase()
        .chars()
        .take(28)
        .collect()
}

/// "Auto-use what's loaded": build the worker pool from the models currently resident on the fleet
/// (`lms ps`) so the swarm runs on what's actually loaded, not (possibly stale) configured model_ids.
/// Returns (pool, planner_model). An empty pool means the fleet has nothing loaded (caller bootstraps
/// or bails). Weights: explicit device override, else speed_weight, else LM Studio PARALLEL, else 1.
fn reconcile_pool_with_fleet(cfg: &SwarmConfig) -> (Vec<SwarmDevice>, Option<String>) {
    let procs = match probe_lms_processes() {
        Ok(p) => p,
        Err(_) => return (Vec::new(), None),
    };
    // One worker per DISTINCT loaded identifier (LM Link routes by identifier); first host wins.
    let mut seen = std::collections::HashSet::new();
    let mut resident: Vec<&LmsProcess> = Vec::new();
    for p in &procs {
        if !p.identifier.is_empty() && seen.insert(p.identifier.clone()) {
            resident.push(p);
        }
    }
    if resident.is_empty() {
        return (Vec::new(), None);
    }
    let pool: Vec<SwarmDevice> = resident
        .iter()
        .map(|p| SwarmDevice {
            id: gen_entry_id(cfg, p.device.as_deref(), &p.identifier),
            model_id: p.identifier.clone(),
            // Weight = an explicit configured override for this model_id (USER WINS — never clamped: a
            // weight above the probed PARALLEL is a legit throughput tactic since agent tasks are bursty, so
            // an extra slot overlaps the idle LM Studio window between an agent's LLM calls), else the
            // configured speed_weight for this host/model (so "a slower machine does less work" actually
            // shapes DISPATCH, not just planner pick — backlog #6), else LM Studio's PARALLEL for this
            // instance, else 1. K6: if an override EXCEEDS the probed PARALLEL we WARN but keep the value.
            weight: {
                let user_w = cfg
                    .devices
                    .iter()
                    .find(|d| d.model_id == p.identifier)
                    .map(|d| d.weight);
                if let (Some(w), Some(par)) = (user_w, p.parallel) {
                    if w > par {
                        eprintln!(
                            "  {} pool weight {w} for {} exceeds LM Studio PARALLEL {par} — kept (oversubscribing can overlap the idle gaps between an agent's LLM calls; if requests just queue with no gain, lower it)",
                            style("⚠").yellow(),
                            p.identifier,
                        );
                    }
                }
                // Concurrency = the node's real capacity: an explicit device override, else LM Studio's
                // PARALLEL, else 1. NOT the speed_weight — LM Studio serves one request per model at a time,
                // so weight > PARALLEL just QUEUES requests on that node and STARVES an idle one (observed:
                // workhorse w3 got 3 tasks, 2 queued, while gabee sat READY). "Faster host does MORE work" is
                // handled separately by pick_device's speed_weight-weighted ROUTING (DeviceCfg.speed_weight),
                // which spreads proportionally more tasks to the fast node OVER TIME via work-stealing (it
                // finishes first and grabs the next ready task) — the correct lever, without oversubscribing.
                user_w.or(p.parallel).unwrap_or(1).max(1)
            },
            enabled: true,
            instances: 1,
            host: p.device.clone(),
        })
        .collect();
    // Planner: keep the configured planner if it is resident; else pick the best resident model for the
    // hardest job (the architect skeleton). QUALITY outranks speed here: a low-quant model (q5/q4/q3/q2)
    // fails the structured skeleton, so prefer a NOT-low-quant model FIRST, then the fastest host
    // (highest speed_weight). speed_weight keys match device+identifier (some identifiers omit the host).
    let planner_rank = |p: &&LmsProcess| -> (u8, u32) {
        let ident = p.identifier.to_lowercase();
        let quant_ok = u8::from(
            !(ident.contains("q2_")
                || ident.contains("q3_")
                || ident.contains("q4_")
                || ident.contains("q5")),
        );
        let hay = format!("{} {}", p.device.as_deref().unwrap_or(""), ident);
        let speed = cfg
            .speed_weights
            .iter()
            .find(|(pat, _)| hay.contains(pat.as_str()))
            .map(|(_, w)| *w)
            .unwrap_or(1);
        (quant_ok, speed)
    };
    let planner = if resident.iter().any(|p| p.identifier == cfg.planner_model) {
        Some(cfg.planner_model.clone())
    } else {
        resident
            .iter()
            .filter(|p| {
                let n = p.identifier.to_lowercase();
                n.contains("27b") || n.contains("dense") || n.contains("coder")
            })
            .max_by_key(|p| planner_rank(p))
            .or_else(|| resident.iter().max_by_key(|p| planner_rank(p)))
            .map(|p| p.identifier.clone())
    };
    (pool, planner)
}

fn gen_entry_id(cfg: &SwarmConfig, device: Option<&str>, identifier: &str) -> String {
    let dev = device
        .map(|d| d.split('.').next().unwrap_or(d).to_lowercase())
        .unwrap_or_default();
    let base = if dev.is_empty() {
        short_model(identifier)
    } else {
        format!("{dev}-{}", short_model(identifier))
    };
    let mut id = base.clone();
    let mut n = 2;
    while cfg.devices.iter().any(|d| d.id == id) {
        id = format!("{base}-{n}");
        n += 1;
    }
    id
}

struct ImportSummary {
    added: Vec<SwarmDevice>,
    skipped_existing: Vec<String>,
    /// (model_id, kept_device, dropped_device) — same identifier loaded on two hosts.
    skipped_collision: Vec<(String, String, String)>,
}

/// Add loaded models as pool entries. Dedup by identifier first (the SAME identifier on two hosts
/// cannot be routed by LM Link → keep the first, flag the rest), then skip identifiers already pooled.
fn import_processes(
    cfg: &mut SwarmConfig,
    procs: &[LmsProcess],
    default_weight: u32,
    enabled: bool,
) -> ImportSummary {
    let mut summary = ImportSummary {
        added: Vec::new(),
        skipped_existing: Vec::new(),
        skipped_collision: Vec::new(),
    };
    let mut kept: HashMap<String, String> = HashMap::new();
    for p in procs {
        let dev_label = p.device.clone().unwrap_or_else(|| "?".to_string());
        if let Some(prev) = kept.get(&p.identifier) {
            summary
                .skipped_collision
                .push((p.identifier.clone(), prev.clone(), dev_label));
            continue;
        }
        kept.insert(p.identifier.clone(), dev_label);
        if cfg.devices.iter().any(|d| d.model_id == p.identifier) {
            summary.skipped_existing.push(p.identifier.clone());
            continue;
        }
        let dev = SwarmDevice {
            id: gen_entry_id(cfg, p.device.as_deref(), &p.identifier),
            model_id: p.identifier.clone(),
            weight: default_weight.max(1),
            enabled,
            instances: 1,
            host: p.device.clone(),
        };
        cfg.devices.push(dev.clone());
        summary.added.push(dev);
    }
    summary
}

fn print_import_summary(s: &ImportSummary) {
    for d in &s.added {
        println!(
            "  {} {:<14} {}{}",
            style("+ added").green().bold(),
            style(&d.id).bold(),
            style(&d.model_id).dim(),
            d.host
                .as_deref()
                .map(|h| format!("  @{h}"))
                .unwrap_or_default()
        );
    }
    for m in &s.skipped_existing {
        println!("  {} {} (already in pool)", style("· skip").dim(), m);
    }
    for (m, keep, drop) in &s.skipped_collision {
        println!(
            "  {} {} on {} — same model_id already taken by {} (LM Link can't distinguish)",
            style("! collision").red().bold(),
            m,
            drop,
            keep
        );
    }
}

/// GOOSE_SWARM_ASK_REPLAN gate. After the user answers the clarify questions, the swarm can either REUSE the
/// first plan (the answers now reach every worker VERBATIM via DispatchRequest.user_decisions — this
/// comment previously claimed they rode research_findings, which never leaves the planner)
/// or RE-PLAN from scratch with the answers folded in. A full re-plan is a ~15-20min tax (skeleton re-draft +
/// re-detailing every subtask) that only pays off when the answers change the plan STRUCTURE; when the ASK was
/// about semantics the reused plan is identical in shape and the workers still see the answers. DEFAULT is now
/// REUSE (skip the re-plan): an A/B on the same ASKING helpdesk spec (UNIQ12 re-plan vs UNIQ12b skip) produced
/// TWO equally-correct full-win apps while the skip saved ~15min — the re-plan's confidence boost (69->88) did
/// NOT yield a better app. Opt INTO the re-plan with GOOSE_SWARM_ASK_REPLAN=1 (also on/true/yes). N=1 with a
/// draft-variance confound (the skip arm reused a higher-confidence 78 plan), so the default stays a knob.
/// UNREACHABLE FROM THE DESKTOP UNTIL NOW — env-only, and env never arrives (LaunchServices). The SIXTH
/// member of that family today, and the one a user actually hits: the engine PRINTS "(set
/// GOOSE_SWARM_ASK_REPLAN=1 to re-plan against them instead)" to a user who has no way to set it.
///
/// MEASURED, allon4-replicate, and it is exactly what Mihai saw on screen: agreement 55, clarity 30 ->
/// min = 30 -> below floor -> ASK (correct: only the user can pin clarity). User answers all 5. Rescore lifts
/// clarity 30 -> 100, so conf becomes min(55,100) = 55 and AGREEMENT now binds. But ask_replan is off, so the
/// engine "keeps this plan", the loop never re-enters, THE RETARGET NEVER FIRES — and the run builds at 55
/// against a floor of 85, on a plan drafted BEFORE the answers existed.
///
/// The default stays REUSE. That is evidence-backed (an A/B on the same asking spec produced two equally
/// correct apps while the skip saved ~15min, and the re-plan's 69->88 confidence bump bought no better app),
/// and n=1 with a draft-variance confound is not enough to move it. What was wrong is that nobody could
/// CHOOSE. Now: env > config > false.
fn ask_replan_enabled(v: Option<String>) -> bool {
    ask_replan_resolved(v, load_config().ask_replan)
}

/// The pure precedence, split out so it is testable (the wrapper reads the process env + config).
fn ask_replan_resolved(env: Option<String>, cfg: Option<bool>) -> bool {
    match env {
        Some(s) => matches!(
            s.trim().to_lowercase().as_str(),
            "1" | "on" | "true" | "yes"
        ),
        None => cfg.unwrap_or(false),
    }
}

/// #129: the answers-win-floor guard resolution. env > config > TRUE. Identical env grammar to
/// `ask_replan_resolved`, but the config-absent default is `true`, not `false` — the guard ships ON so the
/// `ask_replan` foot-gun can't ship a below-floor plan over the answered one. `Option<bool>` config so an
/// omitted field resolves to the ON default (a bare bool would deserialize to false and silently disable it);
/// an explicit env `0`/`off` or a saved config `Some(false)` restores the legacy re-plan for A/B and rollback.
fn answers_win_floor_resolved(env: Option<String>, cfg: Option<bool>) -> bool {
    match env {
        Some(s) => matches!(
            s.trim().to_lowercase().as_str(),
            "1" | "on" | "true" | "yes"
        ),
        None => cfg.unwrap_or(true),
    }
}

fn answers_win_floor_enabled(cfg: Option<bool>) -> bool {
    answers_win_floor_resolved(std::env::var("GOOSE_SWARM_ANSWERS_WIN_FLOOR").ok(), cfg)
}

/// #121 stream-decode retry: env GOOSE_SWARM_STREAM_RETRY wins (0/off/false/no => disabled), else the
/// config field, else default ON. Default-ON because the guarded branch only fires on the deterministic
/// body-drop signature; on a clean run it is inert, and OFF is a known-bad silent false-green.
fn stream_decode_retry_resolved(env: Option<String>, cfg: Option<bool>) -> bool {
    match env {
        Some(s) => matches!(
            s.trim().to_lowercase().as_str(),
            "1" | "on" | "true" | "yes"
        ),
        None => cfg.unwrap_or(true),
    }
}

fn stream_decode_retry_enabled(cfg: Option<bool>) -> bool {
    stream_decode_retry_resolved(std::env::var("GOOSE_SWARM_STREAM_RETRY").ok(), cfg)
}

/// #121: does this accumulated task output carry the deterministic mid-stream body-drop signature? The
/// provider surfaces a dropped HTTP body as ProviderError::NetworkError("Stream decode error: ...") which
/// the agent reply loop yields as assistant TEXT and then BREAKs — so the error sentence is guaranteed to be
/// the LAST chunk. Requiring BOTH the "Stream decode error" marker AND that exact trailing sentence makes
/// this ~zero-false-positive: a genuine verify verdict would have to literally contain the marker string and
/// end with the resend sentence.
fn is_stream_decode_interrupt(text: &str) -> bool {
    text.contains("Stream decode error")
        && text
            .trim_end()
            .ends_with("Please resend your message to try again.")
}

/// #135 straggler-stop gate: env GOOSE_SWARM_STRAGGLER_STOP wins, else config, else default OFF (a timing
