    #[test]
    fn score_skeleton_prefers_wider_flatter_plan() {
        let wc = 3;
        let wide = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":[],"files":["b.py"]},
                {"id":"c","depends_on":[],"files":["c.py"]},
                {"id":"integrate-verify","depends_on":["a","b","c"],"files":["t.py"]}
            ]}"#,
        )
        .unwrap();
        let deep = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":["a"],"files":["b.py"]},
                {"id":"c","depends_on":["b"],"files":["c.py"]},
                {"id":"integrate-verify","depends_on":["a","b","c"],"files":["t.py"]}
            ]}"#,
        )
        .unwrap();
        let sw = score_skeleton(&wide, wc).unwrap();
        let sd = score_skeleton(&deep, wc).unwrap();
        assert!(sw > sd, "wider/flatter should win: wide={sw} deep={sd}");
        // a dep on an unknown task is not a valid DAG -> None (so it can never be picked).
        let bad = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[{"id":"x","depends_on":["nope"],"files":["x.py"]}]}"#,
        )
        .unwrap();
        assert!(score_skeleton(&bad, wc).is_none());
    }

    #[test]
    fn converge_role_normalizes_surface_variety() {
        // Two drafts with the SAME roles (types, parser, cli) but different dirs/case/entry-name, plus the
        // injected sink + a test module. Role-normalized agreement should read near-perfect; the raw metric
        // reads them as heavily divergent (different file strings + task counts).
        let d1 = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"types","depends_on":[],"files":["pkg/types.py"]},
                {"id":"parser","depends_on":["types"],"files":["pkg/parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["pkg/__main__.py"]},
                {"id":"tests","depends_on":["parser"],"files":["tests/test_parser.py"]},
                {"id":"integrate-verify","depends_on":["cli"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let d2 = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"shared-types","depends_on":[],"files":["src/Types.py"]},
                {"id":"the-parser","depends_on":["shared-types"],"files":["src/Parser.py"]},
                {"id":"entry","depends_on":["the-parser"],"files":["src/cli.py"]},
                {"id":"integrate-verify","depends_on":["entry"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let cands = vec![d1, d2];
        let (raw, _) = plan_agreement(&cands, false);
        let (norm, reason) = plan_agreement(&cands, true);
        assert!(norm > raw, "role-normalized {norm} should beat raw {raw}");
        assert!(
            norm >= 85,
            "same 3 roles -> near-perfect agreement, got {norm}"
        );
        assert!(reason.contains("role-normalized"));
    }

    #[test]
    fn canonical_role_folds_entry_but_keeps_distinct_stages() {
        // Entry-point synonyms fold to one role.
        for f in [
            "__main__.py",
            "app.py",
            "src/main.py",
            "cli.py",
            "run.py",
            "entry.py",
        ] {
            assert_eq!(canonical_role(f), "cli", "{f} should be the cli role");
        }
        // Distinct compilation stages must NOT merge (conservative — no over-counting).
        assert_eq!(canonical_role("src/lexer.py"), "lexer");
        assert_eq!(canonical_role("Parser.PY"), "parser");
        assert_eq!(canonical_role("ast.rs"), "ast");
        assert_ne!(canonical_role("lexer.py"), canonical_role("parser.py"));
        // A genuinely different decomposition (split lexer+parser vs one combined parser) stays < perfect.
        let split = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"lexer","depends_on":[],"files":["lexer.py"]},
                {"id":"parser","depends_on":["lexer"],"files":["parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["cli.py"]}
            ]}"#,
        )
        .unwrap();
        let combined = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"parser","depends_on":[],"files":["parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["cli.py"]}
            ]}"#,
        )
        .unwrap();
        let (norm, _) = plan_agreement(&[split, combined], true);
        assert!(
            norm < 100,
            "genuinely different decompositions must not read perfect: {norm}"
        );
    }

    #[test]
    fn plan_agreement_default_path_unchanged() {
        let d = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":["a"],"files":["b.py"]}
            ]}"#,
        )
        .unwrap();
        // Two identical drafts, raw path: spread 0 (40) + jaccard 1 (45) + indep 0 (15) = 100, no marker.
        let (c, r) = plan_agreement(&[d.clone(), d.clone()], false);
        assert_eq!(c, 100);
        assert!(!r.contains("role-normalized"));
        // Single draft -> inert neutral 60 on both paths.
        assert_eq!(plan_agreement(std::slice::from_ref(&d), false).0, 60);
        assert_eq!(plan_agreement(std::slice::from_ref(&d), true).0, 60);
    }

    #[test]
    fn best_subset_agreement_drops_the_outlier() {
        // Three tight drafts (same 3 roles) + one wild outlier (5 modules, disjoint files). The full-set
        // measure is dragged down by the outlier; the best 3-of-4 consensus recovers the tight cluster.
        let tight = |seed: &str| {
            goose_swarm::specs_from_plan_json(&format!(
                r#"{{"subtasks":[
                    {{"id":"types{seed}","depends_on":[],"files":["types.py"]}},
                    {{"id":"core{seed}","depends_on":["types{seed}"],"files":["core.py"]}},
                    {{"id":"cli{seed}","depends_on":["core{seed}"],"files":["cli.py"]}}
                ]}}"#
            ))
            .unwrap()
        };
        let outlier = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["alpha.py"]},
                {"id":"b","depends_on":[],"files":["beta.py"]},
                {"id":"c","depends_on":["a"],"files":["gamma.py"]},
                {"id":"d","depends_on":["b"],"files":["delta.py"]},
                {"id":"e","depends_on":["c","d"],"files":["epsilon.py"]}
            ]}"#,
        )
        .unwrap();
        let pool = vec![tight("1"), tight("2"), tight("3"), outlier];
        let (full, _) = plan_agreement(&pool, true);
        let (subset, reason) = best_subset_agreement(&pool, true, 3);
        assert!(
            subset > full,
            "consensus cluster {subset} should beat the outlier-dragged full set {full}"
        );
        assert!(subset >= 85, "the 3 tight drafts agree on roles: {subset}");
        assert!(reason.contains("consensus 3 of 4"));
        // Inert when the pool has not grown past k: identical to the full-set measure (byte-identical default).
        let two = vec![tight("1"), tight("2")];
        assert_eq!(
            best_subset_agreement(&two, true, 3),
            plan_agreement(&two, true)
        );
    }

    /// THE RESCORE MUST NEVER FLATTER A RUN.
    ///
    /// When the user answers, spec-clarity is re-scored deterministically with the SAME pure function the
    /// first score used — over (open - ANSWERED), never over 0. `ask_max_q` truncates the question list
    /// with a `.take()`, so a run with 8 open decisions that asked 5 still has 3 the user never saw and
    /// goose will guess. Snapping to zero there would raise a number the run did not earn — precisely the
    /// failure the low score exists to prevent (before it, research INVENTED 5 decisions and reported 96).
    #[test]
    fn rescore_credits_only_what_was_actually_answered() {
        // The measured case: 5 open, all 5 asked and answered -> the spec really is pinned.
        assert_eq!(
            spec_clarity_score(true, 5),
            30,
            "the 30 Mihai saw: 100-16*5=20, floored to 30"
        );
        assert_eq!(
            spec_clarity_score(true, 5usize.saturating_sub(5)),
            100,
            "all answered => pinned"
        );

        // The trap: 8 open but the cap asked only 5. THREE are still guesses.
        let still_open = 8usize.saturating_sub(5);
        assert_eq!(still_open, 3);
        let rescored = spec_clarity_score(true, still_open);
        assert_eq!(
            rescored, 52,
            "credit 5 answers, keep charging for the 3 nobody asked about"
        );
        assert!(
            rescored < 100,
            "a truncated ask must NEVER read as a pinned spec"
        );

        // Monotonic: answering more can only raise it, and it can never exceed a pinned spec.
        assert!(spec_clarity_score(true, 3) > spec_clarity_score(true, 5));
        assert!(spec_clarity_score(true, 0) >= spec_clarity_score(true, 1));

        // final = min(agreement, clarity) — the SAME expression as the first score. Agreement is never
        // touched by the rescore: it describes the DAG that actually ships, which IS the pre-answer plan.
        let agreement = 88u8;
        assert_eq!(
            agreement.min(spec_clarity_score(true, 5)),
            30,
            "before: the spec binds"
        );
        assert_eq!(
            agreement.min(spec_clarity_score(true, 0)),
            88,
            "after: agreement binds, not 100"
        );
    }

    #[test]
    fn spec_contract_parsing() {
        let spec =
            "It runs as `python3 -m quorum` which starts the server. REST: POST /api/polls; \
                    GET /api/polls/<id>; GET /api/polls/<id>/results; GET /api/polls (list).";
        assert_eq!(spec_python_entry(spec).as_deref(), Some("quorum"));
        let gets = spec_get_endpoints(spec);
        // The concrete list endpoint is kept; the param'd routes are excluded (no false base-path finding).
        assert_eq!(gets, vec!["/api/polls".to_string()]);
        assert!(!gets.iter().any(|g| g.contains("id") || g.contains('<')));
        // No advertised python entry -> None (a Swift/TS spec no-ops the whole check).
        assert!(spec_python_entry("Build a Swift CLI note-taker").is_none());
        // Port: default 8000, else the advertised one.
        assert_eq!(spec_port("no port mentioned"), 8000);
        assert_eq!(spec_port("the server listens on 127.0.0.1:9100"), 9100);
        // A pure-CLI spec with no GET endpoints yields nothing to curl.
        assert!(spec_get_endpoints("python3 -m tool add x").is_empty());
    }

    #[test]
    fn clarity_fail_closed_reasons() {
        // FAIL-CLOSED (learned nothing → ask): timeout / agent_error / no_final_output, incl. the ": detail" tail.
        assert!(clarity_reason_is_fail_closed("timeout"));
        assert!(clarity_reason_is_fail_closed(
            "agent_error: connection refused"
        ));
        assert!(clarity_reason_is_fail_closed("no_final_output"));
        // FAIL-OPEN (the model DID answer, the JSON just didn't fit): unparseable stays out → no false-ask storm.
        assert!(!clarity_reason_is_fail_closed("unparseable: {truncated"));
        // The clamp value is below the default ask floor (documented on the const) AND is not a producible
        // spec_clarity_score, so a 20 in the breakdown is an unambiguous fail-closed sentinel — checked at
        // runtime against every score the function can emit (a const-vs-const assert is a clippy error).
        for n in 0..=9 {
            assert_ne!(spec_clarity_score(true, n), CLARITY_FAILCLOSED);
            assert_ne!(spec_clarity_score(false, n), CLARITY_FAILCLOSED);
        }
    }

    // ---- #136 DELEGATED DECISIONS ----------------------------------------------------------------
    // The real spec that caused the bug, trimmed to the shapes that matter.
    const LOGFOLD_SPEC: &str = "\
Build `logfold` — a log template miner, in Go, stdlib only.\n\
\n\
## The core\n\
Mask first, then tokenize, then route by a fixed-depth tree. Determinism is required.\n\
\n\
## Calls I'm leaving to you\n\
- **Placeholder vocabulary — typed or flat.** Whether a masked slot renders as a single `<*>` everywhere, or\n\
  keeps its type (`<NUM>`, `<IP>`, `<UUID>`). Typed reads better and diffs more precisely but grows the\n\
  masker surface. Your call, but be consistent between the mask stage and the tree-generalization stage.\n\
- **Template identity across runs.** How a template gets a stable id used by `diff` to match baseline to new\n\
  — hash of the token sequence? This decision is the whole ballgame; make it and defend it in a comment.\n\
";

    #[test]
    fn delegated_decisions_do_not_block_but_a_silent_spec_still_asks() {
        // A: the spec DELEGATES -> recorded, never asked. This is the measured mtp-base case.
        let decisions = vec![
            "Placeholder vocabulary: typed placeholders (<NUM>, <IP>, <UUID>) vs a flat wildcard everywhere. \
             Typed gives better diff precision but grows the masker surface."
                .to_string(),
            "Template identity across runs for diff matching: how a template gets a stable id used by diff to \
             match baseline to new, and what counts as the same template."
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&decisions, LOGFOLD_SPEC);
        assert_eq!(
            delegated.len(),
            2,
            "both are delegated by the spec's own section"
        );
        assert!(blocking.is_empty(), "nothing should block: {blocking:?}");
        // and the confidence recovers, which is the whole point
        assert_eq!(spec_clarity_score(true, decisions.len()), 68);
        assert_eq!(spec_clarity_score(true, blocking.len()), 100);

        // B: a decision the spec NEVER MENTIONS must still block. The gate must not become a blanket silencer.
        let unmentioned = vec![
            "Which authentication provider should the billing portal use for single sign-on"
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&unmentioned, LOGFOLD_SPEC);
        assert_eq!(blocking.len(), 1, "an unmentioned decision MUST still ask");
        assert!(delegated.is_empty());
    }

    #[test]
    fn a_reservation_phrase_outranks_delegation_in_the_same_region() {
        // C: "do NOT guess — ask me" must win, even sitting inside a delegating section, or one loose
        // "your call" would silence the questions the author most wanted asked.
        let spec = "## Calls I'm leaving to you\n\
                    Styling and output formatting are your call.\n\
                    The storage backend and retention window are NOT: do not guess them, ask me.\n";
        let d = vec![
            "storage backend and retention window for the archived records, no sensible default exists"
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&d, spec);
        assert_eq!(blocking.len(), 1, "a reserved decision must still block");
        assert!(delegated.is_empty());
    }

    #[test]
    fn no_delegation_section_is_a_total_passthrough() {
        // F: with nothing delegating, the partition must return the input unchanged — this is what makes the
        // lever byte-identical on the specs that do not use delegation language at all.
        let spec = "Build a CLI that converts markdown to HTML. Support tables and footnotes.";
        let d = vec![
            "whether footnote backlinks render inline or collected at the document foot"
                .to_string(),
            "which markdown flavour to accept for tables".to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&d, spec);
        assert_eq!(blocking, d, "unchanged");
        assert!(delegated.is_empty());
    }

    #[test]
    fn model_prose_appended_to_the_prompt_can_never_manufacture_a_delegation() {
        // THE EXPOSURE, pinned. opts.prompt is appended to by MODEL output at :19660 (research findings) and
        // :19799 (clarify Q&A), and a retarget round re-plans with the enlarged prompt. Research output
        // routinely contains "either is defensible" -- which is one of DELEGATION_MARKERS verbatim. If the
        // partition read the live prompt, the model would be able to silence a question the user needed to
        // answer, which is the exact direction this gate must never fail in.
        let operator_spec =
            "Build a CLI that syncs two folders. It must never delete without a prompt.";
        let model_appended = "\n\n## RESEARCH FINDINGS\n\
             - Conflict resolution: either is defensible, your call whether last-write-wins or newest-mtime \
               wins; pick something sensible and defend it in a comment.\n";
        let polluted = format!("{operator_spec}{model_appended}");
        let decision = vec![
            "Conflict resolution strategy when both sides changed: last-write-wins versus newest-mtime wins, \
             no sensible default exists and guessing wrong silently loses a user's edits"
                .to_string(),
        ];

        // Parsed from the POLLUTED prompt the model would have silenced it...
        let (blocking_bad, delegated_bad) = partition_delegated_decisions(&decision, &polluted);
        assert!(
            !delegated_bad.is_empty() || blocking_bad.len() == 1,
            "sanity: the polluted text is the risky input"
        );

        // ...but parsed from the FROZEN operator spec, which says nothing about delegation, it MUST still ask.
        let (blocking, delegated) = partition_delegated_decisions(&decision, operator_spec);
        assert_eq!(
            blocking.len(),
            1,
            "the operator never delegated this — it must still block"
        );
        assert!(
            delegated.is_empty(),
            "model prose must never create a delegation: {delegated:?}"
        );
    }

    #[test]
    fn a_thin_decision_is_never_assumed_delegated() {
        // Guard the conservative bias: too few significant tokens to match on => keep asking. A false
        // "delegated" silences a real question, which is strictly worse than an unnecessary ask.
        let regions = delegation_regions(LOGFOLD_SPEC);
        assert!(!regions.is_empty());
        assert!(!decision_is_delegated("typed or flat", &regions));
        assert!(!decision_is_delegated("the id", &regions));
    }

    #[test]
    fn delegation_lever_defaults_off_and_env_overrides_config() {
        // Default OFF, and the resolver precedence matches every other lever (env beats config beats default).
        assert!(!delegated_decisions_ok(None));
        assert!(delegated_decisions_ok(Some(true)));
        assert!(!delegated_decisions_ok(Some(false)));
    }

    #[test]
    fn spec_clarity_score_is_continuous_not_a_constant() {
        // Defined product: continuous, decreasing with each material open decision (NOT the old 100/72/50/30
        // buckets); floored at 30 so a very-open-but-defined spec still reads "low, ask".
        assert_eq!(spec_clarity_score(true, 0), 100);
        assert_eq!(spec_clarity_score(true, 1), 84);
        assert_eq!(spec_clarity_score(true, 2), 68);
        assert_eq!(spec_clarity_score(true, 3), 52);
        assert_eq!(spec_clarity_score(true, 9), 30); // floored, count clamped
                                                     // Undefined product: always LOW (<= 30 so it asks regardless of agreement) but VARIES with how many
                                                     // axes are open — so vague specs no longer all snap to a flat 20.
        assert_eq!(spec_clarity_score(false, 0), 30);
        assert_eq!(spec_clarity_score(false, 1), 24);
        assert_eq!(spec_clarity_score(false, 2), 18);
        assert_eq!(spec_clarity_score(false, 9), 8); // floored
                                                     // Ask boundary vs a ~70 floor preserved: defined+0/1 proceed, defined+2 asks, undefined always asks.
        assert!(spec_clarity_score(true, 1) >= 70);
        assert!(spec_clarity_score(true, 2) < 70);
        assert!(spec_clarity_score(false, 0) < 70);
    }

    #[test]
    fn consensus_backbone_pins_only_the_strict_majority() {
        let draft = |ids: &[(&str, &str)]| {
            let subs: Vec<String> = ids
                .iter()
                .map(|(id, file)| format!(r#"{{"id":"{id}","depends_on":[],"files":["{file}"]}}"#))
                .collect();
            goose_swarm::specs_from_plan_json(&format!(r#"{{"subtasks":[{}]}}"#, subs.join(",")))
                .unwrap()
        };
        // 3 drafts: models+cli appear in 2/3; parser in 1/3; a per-module test task must NOT contribute a role.
        let d1 = draft(&[
            ("models", "models.py"),
            ("cli", "__main__.py"),
            ("t", "test_models.py"),
        ]);
        let d2 = draft(&[("models", "models.py"), ("entry", "cli.py")]);
        let d3 = draft(&[("parser", "parser.py"), ("main", "main.py")]);
        let bb = consensus_backbone(&[d1, d2, d3]);
        // cli (folded from __main__/cli/main/entry) in all 3, models in 2 → both pinned; parser (1/3) dropped.
        assert!(bb.contains(&"cli".to_string()), "cli is unanimous: {bb:?}");
        assert!(bb.contains(&"models".to_string()), "models is 2/3: {bb:?}");
        assert!(
            !bb.contains(&"parser".to_string()),
            "parser is only 1/3: {bb:?}"
        );
        assert!(
            !bb.iter().any(|r| r.contains("test")),
            "scaffolding excluded: {bb:?}"
        );
        // <2 drafts → no backbone.
        assert!(consensus_backbone(&[draft(&[("a", "a.py")])]).is_empty());
    }

    #[test]
    fn plan_covers_backbone_requires_every_role() {
        let plan = r#"{"subtasks":[
            {"id":"models","depends_on":[],"files":["pkg/models.py"]},
            {"id":"cli","depends_on":["models"],"files":["pkg/__main__.py"]}
        ]}"#;
        assert!(plan_covers_backbone(plan, &["cli".into(), "models".into()]));
        // A missing role → not covered (the lock was disobeyed).
        assert!(!plan_covers_backbone(
            plan,
            &["cli".into(), "models".into(), "parser".into()]
        ));
        // Invalid JSON → not covered (never adopt an unparseable round-2 plan).
        assert!(!plan_covers_backbone("not json", &["cli".into()]));
    }

    // --- Incremental replan (Phase 1) --------------------------------------------------------------------

    fn spec(id: &str, files: &[&str], deps: &[&str]) -> goose_swarm::TaskSpec {
        goose_swarm::TaskSpec {
            id: id.to_string(),
            description: format!("{id} module"),
            difficulty: goose_swarm::Difficulty::Easy,
            preferred_model: None,
            owned_files: files.iter().map(|s| s.to_string()).collect(),
            deps: deps.iter().map(|s| s.to_string()).collect(),
        }
    }

    #[test]
    fn module_votes_tallies_roles_over_the_full_pool() {
        let d1 = vec![
            spec("core", &["core.py"], &[]),
            spec("cli", &["main.py"], &[]),
        ];
        let d2 = vec![
            spec("core", &["core.py"], &[]),
            spec("entry", &["cli.py"], &[]),
        ];
        let d3 = vec![
            spec("core", &["core.py"], &[]),
            spec("parser", &["parser.py"], &[]),
        ];
        let v = module_votes(&[d1, d2, d3]);
        // core unanimous (3/3); cli folded from main/cli/entry (2/3 — d3 has no entry role); parser 1/3.
        assert_eq!(v.get("core"), Some(&(3, 3)));
        assert_eq!(v.get("cli"), Some(&(2, 3)));
        assert_eq!(v.get("parser"), Some(&(1, 3)));
    }

    #[test]
    fn structural_convergence_clears_80_on_diverse_but_convergent() {
        // A,B share a 5-role core; C renames one (e→x) and adds an extra — a genuinely DIVERSE decomposition
        // that the count-spread metric caps at ~74. struct_conv rewards the shared backbone: A=1.0, B=1.0,
        // C = 4/6 = 0.667 → mean 0.889 → 89, which clears the 80 floor the old metric could not reach.
        let core = |extra: &[(&str, &str)]| {
            let mut v = vec![
                spec("a", &["a.py"], &[]),
                spec("b", &["b.py"], &[]),
                spec("c", &["c.py"], &[]),
                spec("d", &["d.py"], &[]),
            ];
            for (id, f) in extra {
                v.push(spec(id, &[f], &[]));
            }
            v
        };
        let a = core(&[("e", "e.py")]);
        let b = core(&[("e", "e.py")]);
        let c = core(&[("x", "x.py"), ("extra", "extra.py")]);
        let (conv, _) = structural_convergence(&[a, b, c]);
        assert_eq!(
            conv, 89,
            "diverse-but-convergent drafts must clear the 80 floor"
        );

        // Fragmented: each draft invents its own modules, nothing shared → won't stop (F3 guarantee).
        let f1 = vec![spec("a", &["a1.py"], &[]), spec("b", &["a2.py"], &[])];
        let f2 = vec![spec("a", &["b1.py"], &[]), spec("b", &["b2.py"], &[])];
        let f3 = vec![spec("a", &["c1.py"], &[]), spec("b", &["c2.py"], &[])];
        let (frag, _) = structural_convergence(&[f1, f2, f3]);
        assert_eq!(frag, 0, "fragmented drafts must NOT fake convergence");
    }

    #[test]
    fn partition_freezes_only_unanimous_and_downward_closed() {
        // core + cli unanimous, eval only 2/3. cli deps on eval, so even though cli's own role is unanimous it
        // CANNOT freeze (downward-closure): its dep eval is dirty. core (root, unanimous) freezes.
        let mk = |eval: bool| {
            let mut s = vec![
                spec("core", &["core.py"], &[]),
                spec("cli", &["main.py"], &["core", "eval"]),
            ];
            if eval {
                s.push(spec("eval", &["eval.py"], &["core"]));
            } else {
                s.push(spec("score", &["score.py"], &["core"])); // a different role, so eval is not unanimous
            }
            s
        };
        let valid = vec![mk(true), mk(true), mk(false)];
        let votes = module_votes(&valid);
        let source = mk(true); // the best draft = one that HAS eval
        let (frozen, dirty) = partition_frozen_dirty(&votes, &source);
        let fids: Vec<&str> = frozen.iter().map(|t| t.id.as_str()).collect();
        assert!(fids.contains(&"core"), "core is unanimous root: {fids:?}");
        assert!(
            !fids.contains(&"cli"),
            "cli deps on dirty eval → not frozen: {fids:?}"
        );
        assert!(
            !fids.contains(&"eval"),
            "eval is only 2/3 → dirty: {fids:?}"
        );
        assert!(dirty.contains(&"eval".to_string()) && dirty.contains(&"cli".to_string()));
        // P0-1 invariant: EVERY frozen task's deps resolve inside the frozen set (never dangles).
        let frozen_ids: std::collections::BTreeSet<&str> =
            frozen.iter().map(|t| t.id.as_str()).collect();
        for t in &frozen {
            for d in &t.deps {
                assert!(
                    frozen_ids.contains(d.as_str()),
                    "frozen `{}` deps on non-frozen `{d}`",
                    t.id
                );
            }
        }
    }

    #[test]
    fn partition_downward_closure_freezes_a_full_chain_when_all_unanimous() {
        // core <- eval <- cli, all unanimous → the whole chain freezes (closure is satisfied at every level).
        let chain = || {
            vec![
                spec("core", &["core.py"], &[]),
                spec("eval", &["eval.py"], &["core"]),
                spec("cli", &["main.py"], &["eval"]),
            ]
        };
        let valid = vec![chain(), chain(), chain()];
        let votes = module_votes(&valid);
        let (frozen, dirty) = partition_frozen_dirty(&votes, &chain());
        assert_eq!(frozen.len(), 3, "all three freeze");
        assert!(dirty.is_empty());
    }

    #[test]
    fn validate_frozen_interfaces_accepts_a_clean_wire_and_rejects_the_r2_breaks() {
        let frozen = vec![spec("core", &["core.py"], &[])];
        // (ok) a dirty module that deps on the frozen id and owns a NEW role.
        let clean = vec![
            spec("cli", &["main.py"], &["core"]),
            spec("integrate-verify", &[], &["core", "cli"]),
        ];
        assert!(validate_frozen_interfaces(&frozen, &clean).is_ok());
        // (ii) dep on a frozen id that does not exist (a changed/renamed frozen id) → unknown dep → reject.
        let bad_dep = vec![spec("cli", &["main.py"], &["kore"])];
        assert!(validate_frozen_interfaces(&frozen, &bad_dep).is_err());
        // (iii) a cycle through a frozen node: give the frozen node a dep on a dirty node, dirty deps back.
        let frozen_cyc = vec![spec("core", &["core.py"], &["cli"])];
        let dirty_cyc = vec![spec("cli", &["main.py"], &["core"])];
        assert!(validate_frozen_interfaces(&frozen_cyc, &dirty_cyc).is_err());
        // (iv) a dirty file whose canonical role collides with a frozen role → reject.
        let role_collide = vec![spec("core2", &["pkg/core.py"], &[])];
        assert!(validate_frozen_interfaces(&frozen, &role_collide).is_err());
        // (b) a dirty task that reuses a frozen id → reject.
        let id_reuse = vec![spec("core", &["other.py"], &[])];
        assert!(validate_frozen_interfaces(&frozen, &id_reuse).is_err());
    }

    #[test]
    fn plan_json_from_specs_roundtrips() {
        let specs = vec![
            spec("core", &["core.py", "types.py"], &[]),
            spec("cli", &["main.py"], &["core"]),
        ];
        let json = plan_json_from_specs(&specs);
        let back = goose_swarm::specs_from_plan_json(&json).unwrap();
        assert_eq!(back.len(), 2);
        assert_eq!(back[0].id, "core");
        assert_eq!(back[0].owned_files, vec!["core.py", "types.py"]);
        assert_eq!(back[1].deps, vec!["core"]);
    }

