    #[test]
    fn rust_empty_stub_entry_is_flagged() {
        // exit-0 with no output = an unwired `fn main(){}` stub (kvstore's failure) -> flagged.
        assert!(rust_entry_is_empty_stub(true, ""));
        assert!(rust_entry_is_empty_stub(true, "   \n  "));
        // a real CLI prints usage -> not a stub.
        assert!(!rust_entry_is_empty_stub(true, "Usage: kv <COMMAND>\n"));
        // a non-zero exit is a different failure mode (panic/error path), not the empty-stub case.
        assert!(!rust_entry_is_empty_stub(false, ""));
    }

    /// The fan-outs hold `DeviceCfg` (the resolved runtime pool), not the config-file `SwarmDevice`
    /// that `dev()` above builds. Two structs, both with a `weight` field, and the compiler is the
    /// only thing that tells them apart.
    fn cfg_w(id: &str, model: &str, weight: u32) -> DeviceCfg {
        DeviceCfg {
            id: id.to_string(),
            model_id: model.to_string(),
            weight,
            enabled: true,
            speed_weight: 1,
        }
    }

    #[test]
    fn fleet_slot_models_counts_slots_not_devices() {
        // The defect: three weight-2 devices are SIX slots, and every planning fan was sized at 3.
        let pool = vec![
            cfg_w("a", "m-a", 2),
            cfg_w("b", "m-b", 2),
            cfg_w("c", "m-c", 2),
        ];
        let slots = fleet_slot_models(&pool);
        assert_eq!(slots.len(), 6, "3 devices x weight 2 must yield 6 slots");
        assert_eq!(slots.iter().filter(|m| *m == "m-a").count(), 2);

        // THE OTHER DIRECTION, or this would pass on a helper that blindly doubles everything: a
        // weight-1 node must still get exactly one, which is the property the original docstring
        // promised and the only reason the cap existed at all.
        let mixed = vec![cfg_w("a", "m-a", 1), cfg_w("b", "m-b", 3)];
        let slots = fleet_slot_models(&mixed);
        assert_eq!(slots.len(), 4);
        assert_eq!(slots.iter().filter(|m| *m == "m-a").count(), 1);

        // A zero/absent weight must not erase a device from the fleet entirely.
        assert_eq!(fleet_slot_models(&[cfg_w("a", "m-a", 0)]).len(), 1);
        assert!(fleet_slot_models(&[]).is_empty());
    }

    #[test]
    fn slot_expansion_does_not_widen_the_skeleton_draft_vote() {
        // The draft path dedups through a HashSet before sizing the vote, so feeding it slots must
        // change NOTHING. Asserted because the dedup's own comment records duplicates being measured
        // dead — 6 requested, exactly 3 survived — and a future edit that drops the dedup would
        // otherwise silently turn a concurrency fix into a doubled, mostly-dead draft fan.
        let pool = vec![
            cfg_w("a", "m-a", 2),
            cfg_w("b", "m-b", 2),
            cfg_w("c", "m-c", 2),
        ];
        let distinct: Vec<String> = pool.iter().map(|d| d.model_id.clone()).collect();
        let slots = fleet_slot_models(&pool);
        let dedup = |models: &[String]| -> usize {
            let mut seen = std::collections::HashSet::new();
            std::iter::once("planner".to_string())
                .chain(models.iter().cloned())
                .filter(|m| seen.insert(m.clone()))
                .count()
        };
        assert_eq!(
            dedup(&slots),
            dedup(&distinct),
            "the vote width must be unchanged"
        );
        assert_eq!(dedup(&slots), 4, "planner + 3 distinct models");
    }

    /// THE CONTRACT F350 ACTUALLY SHIPPED, which nothing was checking.
    ///
    /// `fanout_caps_one_call_per_device` above still passes, and that is the problem: its fixture is three
    /// UNIQUE device strings, while every production caller now passes `fleet_slot_models()` — each model_id
    /// repeated `weight` times. So the guard that exists asserts one-call-per-device on a shape the engine no
    /// longer sends, and the shape it does send (six entries, three models) was asserted nowhere. F350 tested
    /// that the LIST is six long; the list length is the shape, and running six at once is the contract.
    #[tokio::test]
    async fn fanout_runs_one_call_per_slot_so_a_weight_two_device_takes_two() {
        use std::sync::atomic::AtomicUsize;
        // Exactly what fleet_slot_models() yields for the bed: 3 devices x weight 2.
        let slots = fleet_slot_models(&[
            cfg_w("a", "m-a", 2),
            cfg_w("b", "m-b", 2),
            cfg_w("c", "m-c", 2),
        ]);
        assert_eq!(slots.len(), 6);
        let max_per_device = Arc::new(Mutex::new(HashMap::<String, usize>::new()));
        let inflight = Arc::new(Mutex::new(HashMap::<String, usize>::new()));
        let total = Arc::new(AtomicUsize::new(0));
        let max_total = Arc::new(AtomicUsize::new(0));
        let items: Vec<usize> = (0..18).collect();
        let (mpd, inf, tot, mtot) = (
            max_per_device.clone(),
            inflight.clone(),
            total.clone(),
            max_total.clone(),
        );
        let results = fanout_over_fleet(slots, items, move |i, dev| {
            let (mpd, inf, tot, mtot) = (mpd.clone(), inf.clone(), tot.clone(), mtot.clone());
            async move {
                let cur = {
                    let mut g = inf.lock().unwrap();
                    let e = g.entry(dev.clone()).or_insert(0);
                    *e += 1;
                    *e
                };
                {
                    let mut m = mpd.lock().unwrap();
                    let e = m.entry(dev.clone()).or_insert(0);
                    if cur > *e {
                        *e = cur;
                    }
                }
                let t = tot.fetch_add(1, Ordering::SeqCst) + 1;
                mtot.fetch_max(t, Ordering::SeqCst);
                tokio::time::sleep(std::time::Duration::from_millis(5)).await;
                tot.fetch_sub(1, Ordering::SeqCst);
                *inf.lock().unwrap().get_mut(&dev).unwrap() -= 1;
                i
            }
        })
        .await;
        assert_eq!(results.len(), 18, "every item returns a result");
        // Three DISTINCT models, six slots: the duplicates must not collapse the pool.
        assert_eq!(
            max_per_device.lock().unwrap().len(),
            3,
            "work-stealing should still touch every device"
        );
        // The whole point of the change: a weight-2 device runs TWO at once, and the fleet reaches SIX.
        for (dev, &m) in max_per_device.lock().unwrap().iter() {
            assert!(
                m <= 2,
                "device {dev} exceeded its weight with {m} concurrent"
            );
        }
        assert!(
            max_total.load(Ordering::SeqCst) <= 6,
            "never more than the slot count"
        );
        assert!(
            max_total.load(Ordering::SeqCst) > 3,
            "if this caps at 3 the fan is still sized by DEVICES and F350 is inert: got {}",
            max_total.load(Ordering::SeqCst)
        );
    }

    #[tokio::test]
    async fn fanout_caps_one_call_per_device() {
        use std::sync::atomic::AtomicUsize;
        let devices = vec!["d0".to_string(), "d1".to_string(), "d2".to_string()];
        let max_per_device = Arc::new(Mutex::new(HashMap::<String, usize>::new()));
        let inflight = Arc::new(Mutex::new(HashMap::<String, usize>::new()));
        let total = Arc::new(AtomicUsize::new(0));
        let max_total = Arc::new(AtomicUsize::new(0));
        let items: Vec<usize> = (0..9).collect();
        let (mpd, inf, tot, mtot) = (
            max_per_device.clone(),
            inflight.clone(),
            total.clone(),
            max_total.clone(),
        );
        let results = fanout_over_fleet(devices, items, move |i, dev| {
            let (mpd, inf, tot, mtot) = (mpd.clone(), inf.clone(), tot.clone(), mtot.clone());
            async move {
                let cur = {
                    let mut g = inf.lock().unwrap();
                    let e = g.entry(dev.clone()).or_insert(0);
                    *e += 1;
                    *e
                };
                {
                    let mut m = mpd.lock().unwrap();
                    let e = m.entry(dev.clone()).or_insert(0);
                    if cur > *e {
                        *e = cur;
                    }
                }
                let t = tot.fetch_add(1, Ordering::SeqCst) + 1;
                mtot.fetch_max(t, Ordering::SeqCst);
                tokio::time::sleep(std::time::Duration::from_millis(5)).await;
                tot.fetch_sub(1, Ordering::SeqCst);
                *inf.lock().unwrap().get_mut(&dev).unwrap() -= 1;
                i * 2
            }
        })
        .await;
        assert_eq!(results.len(), 9, "every item returns a result");
        for (dev, &m) in max_per_device.lock().unwrap().iter() {
            assert!(
                m <= 1,
                "device {dev} ran {m} concurrent calls; must be <= 1"
            );
        }
        assert!(
            max_total.load(Ordering::SeqCst) <= 3,
            "no more than 3 concurrent across a 3-device fleet"
        );
        assert_eq!(
            max_per_device.lock().unwrap().len(),
            3,
            "work-stealing should use every device"
        );
    }

    #[test]
    fn model_active_params_and_weak_bump() {
        // MoE active marker wins over the dense total (a3b = 3B active, weaker than the 35B total).
        assert_eq!(model_active_params_b("qwen/qwen3.6-35b-a3b"), Some(3));
        // dense size when there is no active marker.
        assert_eq!(model_active_params_b("qwen/qwen3.6-27b"), Some(27));
        assert_eq!(model_active_params_b("llama-3.1-8b-instruct"), Some(8));
        // Mixtral-style NxMb -> the per-expert size M as the active proxy.
        assert_eq!(model_active_params_b("mixtral-8x7b-instruct"), Some(7));
        assert_eq!(model_active_params_b("some-unsized-model"), None);
        // Weaker (fewer active params) -> bigger bump (ask sooner); strong -> no bump.
        assert_eq!(ask_floor_weak_bump(Some(27)), 5);
        assert_eq!(ask_floor_weak_bump(Some(3)), 15); // a3b MoE
        assert_eq!(ask_floor_weak_bump(Some(70)), 0); // strong
        assert_eq!(ask_floor_weak_bump(None), 5);
        assert!(ask_floor_weak_bump(Some(3)) > ask_floor_weak_bump(Some(27)));
    }

    #[test]
    fn detect_language_defaults_python_and_honors_cues() {
        // No cue -> Python (the validated baseline default).
        assert_eq!(
            detect_language("a CLI markdown to HTML renderer", &[]),
            TargetLang::Python
        );
        // Explicit spec cues win.
        assert_eq!(
            detect_language("build a TypeScript CLI todo app", &[]),
            TargetLang::TypeScript
        );
        assert_eq!(
            detect_language("a Rust CLI using cargo", &[]),
            TargetLang::Rust
        );
        assert_eq!(
            detect_language("a golang command line tool", &[]),
            TargetLang::Go
        );
        // A named-but-unprofiled language is honored (generic), never forced to Python.
        assert_eq!(detect_language("a Ruby CLI gem", &[]), TargetLang::Other);
        // APP8 regression: an explicit LANG=Python wins over ".json" (which contains ".js") — previously
        // mis-detected as TypeScript and the JSON validator was built in the wrong language.
        assert_eq!(
            detect_language(
                "LANG=Python — a CLI JSON-schema validator: validate SCHEMA.json DATA.json",
                &[]
            ),
            TargetLang::Python
        );
        // ".json" with no explicit language is NOT TypeScript (word-boundary ext match) -> default Python.
        assert_eq!(
            detect_language("a CLI that reads config.json and prints a report", &[]),
            TargetLang::Python
        );
        // a real .js file mention IS TypeScript; node.js name IS TypeScript.
        assert_eq!(
            detect_language("a CLI whose entry is bin/cli.js", &[]),
            TargetLang::TypeScript
        );
        assert_eq!(
            detect_language("a node.js CLI that validates data.json", &[]),
            TargetLang::TypeScript
        );
        // Amendment: the existing files' extensions are the strongest signal, overriding a bare spec.
        assert_eq!(
            detect_language("add a --json flag", &["index.ts".into(), "util.ts".into()]),
            TargetLang::TypeScript
        );
        assert_eq!(
            detect_language(
                "add a --json flag",
                &["cli.py".into(), "detector.py".into()]
            ),
            TargetLang::Python
        );
    }

    #[test]
    fn clarify_answer_flips_detected_language_forcing_replan() {
        // The ASK-answer fix folds the user's clarifications into the spec BEFORE language detection, so a
        // runtime choice in the answer is honored. This is the exact miss it fixes: a vague spec defaults to
        // Python, the user picks Rust, and previously the answer went only into research findings (which
        // detect_language never reads) so the run silently stayed Python. Appending the Q&A block (which
        // embeds "A: Rust ...") must flip the detected language — that flip is what forces the re-plan.
        let spec =
            "Build a small command-line developer utility that saves time in day-to-day work. \
                    Pick something genuinely useful and make it good.";
        assert_eq!(detect_language(spec, &[]), TargetLang::Python);
        // The real Q&A block shape from ask_clarifying_questions (question + verbatim answer).
        let qa = "\n\n[User clarifications incorporated into the spec]\n\n\
                  USER CLARIFICATIONS (authoritative — they resolve ambiguity in the spec above; honor them):\n\
                  Q: What runtime should it be?\nA: Rust (faster, single binary)\n";
        let amended = format!("{spec}{qa}");
        assert_eq!(detect_language(&amended, &[]), TargetLang::Rust);
        // The fix's decision: a differing language BEFORE vs AFTER folding the answer is what triggers the
        // forced re-plan (a reused Python-shaped plan cannot honor a switch to Rust).
        assert_ne!(detect_language(&amended, &[]), detect_language(spec, &[]));
    }

    #[test]
    fn target_lang_profile_python_is_unchanged_others_translate() {
        // Python keeps the exact original scaffolding and an EMPTY directive (prompt byte-identical).
        assert!(TargetLang::Python.directive().is_empty());
        assert!(TargetLang::Python.entry_clause().contains("cli.py"));
        assert_eq!(TargetLang::Python.test_cmd(), "python3 -m pytest");
        // Non-Python: forceful directive + language-correct entry point + test runner, no Python mandate.
        let ts = TargetLang::TypeScript;
        assert!(ts.directive().contains("TARGET LANGUAGE: TypeScript"));
        assert!(ts.entry_clause().contains("index.ts") && !ts.entry_clause().contains("cli.py"));
        assert!(ts.test_cmd().contains("vitest") || ts.test_cmd().contains("npm"));
        assert!(TargetLang::Rust.entry_clause().contains("main.rs"));
        assert_eq!(TargetLang::Go.test_cmd(), "go test ./...");
        // Source/test-file predicates: Python arm = the original `.py` behavior; non-Python is language-correct.
        assert!(
            TargetLang::Python.is_source_file("foo.py")
                && !TargetLang::Python.is_source_file("foo.ts")
        );
        assert!(
            ts.is_source_file("foo.ts")
                && ts.is_source_file("foo.tsx")
                && !ts.is_source_file("foo.py")
        );
        assert!(
            TargetLang::Python.is_test_file("test_foo.py")
                && TargetLang::Python.is_test_file("conftest.py")
        );
        assert!(ts.is_test_file("foo.test.ts") && !ts.is_test_file("foo.ts"));
        // Other is now AGNOSTIC: it matches a broad set of code extensions (e.g. Ruby) so CONTRACTS work for
        // any language, but still rejects non-source files.
        assert!(TargetLang::Other.is_source_file("foo.rb"));
        assert!(!TargetLang::Other.is_source_file("README.md"));
    }

    #[test]
    fn parse_ast_review_reads_findings_and_degrades() {
        let r = parse_ast_review(
            r#"{"modules": 6, "findings": ["app.orphan is imported by no non-test module"]}"#,
        );
        assert!(r.ran);
        assert_eq!(r.modules, 6);
        assert_eq!(r.findings.len(), 1);
        // a reviewer hiccup (non-JSON stderr/traceback) must degrade to ran=false, never a hard failure.
        let bad = parse_ast_review("Traceback (most recent call last): SyntaxError");
        assert!(!bad.ran);
        assert!(bad.findings.is_empty());
    }

